(function(){
  function scalar(s){
    s=String(s).trim();
    if(s===''||s==='~'||s==='null'||s==='Null'||s==='NULL') return null;
    if(s==='true'||s==='True'||s==='TRUE') return true;
    if(s==='false'||s==='False'||s==='FALSE') return false;
    if((s[0]==='"'&&s.slice(-1)==='"')||(s[0]==="'"&&s.slice(-1)==="'")) return s.slice(1,-1);
    if(/^-?\d+$/.test(s)) return parseInt(s,10);
    if(/^-?\d*\.\d+$/.test(s)) return parseFloat(s);
    return s;
  }
  function inline(s){
    s=String(s).trim();
    if(s[0]==='['){
      var inner=s.slice(1,s.length-1).trim();
      if(inner==='') return [];
      return inner.split(',').map(function(x){return scalar(x);});
    }
    if(s[0]==='{'){
      var inner=s.slice(1,s.length-1).trim(); var o={};
      if(inner!=='') inner.split(',').forEach(function(p){
        var ci=p.indexOf(':'); if(ci<0) return;
        var k=p.slice(0,ci).trim(), v=p.slice(ci+1).trim(); o[scalar(k)]=scalar(v);
      });
      return o;
    }
    return scalar(s);
  }
  function parseYaml(text){
    var raw=String(text).replace(/\r/g,'').split('\n');
    var lines=[];
    for(var k=0;k<raw.length;k++){ var ln=raw[k].replace(/\t/g,'  '); var tr=ln.trim();
      if(tr===''||tr[0]==='#') continue;
      var ind=ln.length-ln.replace(/^ +/,'').length; lines.push({indent:ind,text:tr}); }
    var pos=0;
    function parseMap(indent){
      var obj={};
      while(pos<lines.length && lines[pos].indent===indent && lines[pos].text[0]!=='-'){
        var line=lines[pos].text, ci=line.indexOf(':'); if(ci<0){pos++;continue;}
        var key=line.slice(0,ci).trim(), val=line.slice(ci+1).trim(); pos++;
        if(val===''){
          if(pos<lines.length && lines[pos].indent>indent){ obj[scalar(key)]=parseNode(lines[pos].indent); }
          else obj[scalar(key)]=null;
        } else obj[scalar(key)]=inline(val);
      }
      return obj;
    }
    function parseSeq(indent){
      var arr=[]; var dash=lines[pos].indent;
      while(pos<lines.length && lines[pos].indent===dash && lines[pos].text[0]==='-'){
        var t=lines[pos].text.slice(1).trim(); pos++;
        if(t===''){ arr.push(parseNode(indent+1)); }
        else if(t.indexOf(':')>=0 && /^[A-Za-z0-9_\- ]+?:/.test(t)){
          pos--; lines[pos].text=t; arr.push(parseMap(indent+2<lines[pos].indent?indent+2:indent+2));
        } else arr.push(inline(t));
      }
      return arr;
    }
    function parseNode(indent){
      if(pos>=lines.length) return null;
      if(lines[pos].text[0]==='-') return parseSeq(lines[pos].indent);
      return parseMap(indent);
    }
    return parseNode(0);
  }
  function toJson(yamlText){
    try{ var v=parseYaml(yamlText); return {value:JSON.stringify(v,null,2)}; }
    catch(e){ return {error:'YAML 解析失败: '+e.message}; }
  }
  function yamlVal(v,ind){
    var pad=new Array(ind+1).join('  ');
    if(v===null||v===undefined) return 'null';
    if(typeof v==='boolean'||typeof v==='number') return String(v);
    if(typeof v==='string'){
      if(/[:#\-?\[\]\{\},&*!|>'"%@`\n]/.test(v)||v===''||/^\s|\s$/.test(v)) return '"'+v.replace(/"/g,'\\"')+'"';
      return v;
    }
    if(Array.isArray(v)){
      if(v.length===0) return '[]';
      return '[\n'+v.map(function(x){return pad+'  - '+yamlVal(x,ind+1).replace(/^\n+/,'');}).join('\n')+'\n'+pad+']';
    }
    if(typeof v==='object'){
      var ks=Object.keys(v); if(ks.length===0) return '{}';
      return ks.map(function(k){ return pad+k+': '+yamlVal(v[k],ind); }).join('\n');
    }
    return String(v);
  }
  function toYaml(jsonText){
    try{ var v=JSON.parse(jsonText); return {value:yamlVal(v,0)}; }
    catch(e){ return {error:'JSON 解析失败: '+e.message}; }
  }
  var API={toJson:toJson,toYaml:toYaml,parseYaml:parseYaml};
  if(typeof module!=='undefined'&&module.exports)module.exports=API;
  if(typeof window!=='undefined')window.__YqForge__=API;
})();
